<?php
require dirname(__DIR__).'/includes/bootstrap.php'; require_permission('attendance.manage'); $bid=current_branch_id();
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $staffId=(int)$_POST['staff_id']; $date=$_POST['attendance_date']??today(); $action=$_POST['_action']??'save'; q('INSERT IGNORE INTO attendance(branch_id,staff_id,attendance_date,status,created_by,created_at) VALUES(?,?,?,"present",?,NOW())',[$bid,$staffId,$date,$_SESSION['user_id']]); if($action==='clock_in') q('UPDATE attendance SET clock_in=IFNULL(clock_in,NOW()),status=IF(TIME(NOW())>"09:00:00","late","present") WHERE branch_id=? AND staff_id=? AND attendance_date=?',[$bid,$staffId,$date]); elseif($action==='clock_out') q('UPDATE attendance SET clock_out=NOW() WHERE branch_id=? AND staff_id=? AND attendance_date=?',[$bid,$staffId,$date]); else q('UPDATE attendance SET status=?,notes=?,created_by=? WHERE branch_id=? AND staff_id=? AND attendance_date=?',[$_POST['status'],trim($_POST['notes']??''),$_SESSION['user_id'],$bid,$staffId,$date]); audit('update','attendance',$staffId,['date'=>$date,'action'=>$action]); flash('success','Attendance updated.'); redirect('modules/attendance.php?date='.$date);}
$date=$_GET['date']??today(); if(!valid_date($date))$date=today(); $rows=all('SELECT st.id staff_id,st.full_name,st.role_title,a.* FROM staff st LEFT JOIN attendance a ON a.staff_id=st.id AND a.attendance_date=? WHERE st.branch_id=? AND st.status="active" ORDER BY st.full_name',[$date,$bid]); $title='Staff Attendance'; $subtitle='Clock in, clock out, late, absent and leave records.'; include dirname(__DIR__).'/includes/header.php';?><div class="toolbar"><form><input type="date" name="date" value="<?=e($date)?>" data-autosubmit></form></div><div class="table-wrap"><table><thead><tr><th>Staff</th><th>Role</th><th>Clock In</th><th>Clock Out</th><th>Status</th><th>Notes</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?></td><td><?=e($r['role_title'])?></td><td><?=e($r['clock_in']??'')?></td><td><?=e($r['clock_out']??'')?></td><td><?=e($r['status']??'not marked')?></td><td><?=e($r['notes']??'')?></td><td><form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="staff_id" value="<?=e($r['staff_id'])?>"><input type="hidden" name="attendance_date" value="<?=e($date)?>"><button class="btn small" name="_action" value="clock_in">Clock In</button><button class="btn small secondary" name="_action" value="clock_out">Clock Out</button></form><form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="staff_id" value="<?=e($r['staff_id'])?>"><input type="hidden" name="attendance_date" value="<?=e($date)?>"><select name="status"><option value="present">Present</option><option value="late">Late</option><option value="absent">Absent</option><option value="leave">Leave</option><option value="off">Off</option></select><input name="notes" placeholder="Notes"><button class="btn small light" name="_action" value="save">Save</button></form></td></tr><?php endforeach;?></tbody></table></div><?php include dirname(__DIR__).'/includes/footer.php'; ?>